[{"pattern": "~아/어도", "exp": "even if; even though", "example_in_sentence": "발전해도"}, {"pattern": "~다는 뜻이다", "exp": "it means that", "example_in_sentence": "완벽하지 않다는 뜻이에요"}], "analysis": []}, {"text": "앞으로 더 정확한 확인 방법이 필요할 것 같아요.", "idx": 10, "translation": "In the future, more accurate verification methods will likely be needed.", "vocab": [{"ko": "앞으로", "en": "in the future; ahead", "note": ""}, {"ko": "정확하다", "en": "to be accurate; to be precise", "note": ""}, {"ko": "방법", "en": "method; way", "note": ""}], "grammar": [{"pattern": "~을/를 것 같다", "exp": "it seems that; it appears that; likely will", "example_in_sentence": "필요할 것 같아요"}], "analysis": []}, {"text": "전문가들은 이런 일이 한국에서도 일어날 수 있다고 말해요.", "idx": 11, "translation": "Experts say that this kind of thing could happen in Korea as well.", "vocab": [{"ko": "전문가", "en": "expert; specialist", "note": ""}, {"ko": "일어나다", "en": "to happen; to occur", "note": ""}], "grammar": [{"pattern": "~을/를 수 있다", "exp": "can; is possible to; may", "example_in_sentence": "일어날 수 있다고"}], "analysis": []}, {"text": "부모님들은 자녀의 인터넷 사용을 더 주의 깊게 살펴봐야 할 것 같아요.", "idx": 12, "translation": "Parents will likely need to watch their children''s internet use more carefully.", "vocab": [{"ko": "부모님", "en": "parents", "note": "부모 + 님 (honorific)"}, {"ko": "자녀", "en": "child; children", "note": "formal/written form"}, {"ko": "인터넷", "en": "internet", "note": ""}, {"ko": "주의 깊다", "en": "to be careful; to be attentive", "note": "주의 + 깊다"}], "analysis": [{"type": "grammar", "label": "~아/어야 하다", "exp": "''Must; need to''. 살펴보다 → 살펴봐야 하다 = need to look into.", "example_in_sentence": "살펴봐야 할"}, {"type": "grammar", "label": "~(으)ㄹ 것 같다", "exp": "''It seems; probably''. 하다 → 할 것 같아요 = it seems (they) will have to.", "example_in_sentence": "할 것 같아요"}]}], "version": "p3"}', updated_at = now() where article_id = 'mosfmrvfjg8r' and md5(translation) = '9a00baade7389d0e349d36f43c2c0d6f';
update public.article_cache set translation = '{"texts": ["There is a snake called chrysopelea. This snake is called a ''flying snake.'' It is a really amazing snake.", "This snake can fly in the sky. It moves from tree to tree. It moves just like a bird.", "The flying snake can go very far. It can fly up to 100 meters. It is a distance as long as a soccer field.", "This snake flattens its body. Then it glides through the air. It is a really smart animal."], "sentences": [{"text": "크리소펠레아(chrysopelea)라는 뱀이 있어요.", "translation": "There is a snake called chrysopelea.", "vocab": [{"ko": "뱀", "en": "snake"}, {"ko": "있다", "en": "there is; to exist"}], "analysis": [{"type": "grammar", "label": "~라는", "exp": "Quotative particle marking a name or label. Attached to nouns to indicate ''called'' or ''named''. Form: noun + 라는.", "example_in_sentence": "크리소펠레아(chrysopelea)라는"}, {"type": "grammar", "label": "~어요", "exp": "Present tense polite ending for statements. Conjugation: 있다 → 있어요.", "example_in_sentence": "있어요"}]}, {"text": "이 뱀은 ''나는 뱀''이라고 불려요.", "translation": "This snake is called a ''flying snake.''", "vocab": [{"ko": "이", "en": "this"}, {"ko": "날다", "en": "to fly"}, {"ko": "불리다", "en": "to be called"}], "analysis": [{"type": "grammar", "label": "~는 (noun modifier)", "exp": "Describes the noun that follows. ㄹ-stem verbs drop ㄹ before ~는: 날다 → 나는 뱀 (a flying snake). (날으는 is a common misspelling.)", "example_in_sentence": "나는"}, {"type": "grammar", "label": "~이라고", "exp": "Quotative particle introducing reported speech or labels. Marks what something is called or said. Form: noun + 이라고.", "example_in_sentence": "''나는 뱀''이라고"}, {"type": "grammar", "label": "~아/어요 (polite ending)", "exp": "The everyday polite ending. 불리다 (to be called) → 불려요 = is called.", "example_in_sentence": "불려요"}]}, {"text": "정말 신기한 뱀이에요.", "translation": "It is a truly amazing snake.", "vocab": [{"ko": "정말", "en": "really; truly"}, {"ko": "신기하다", "en": "to be amazing; to be wonderful"}], "analysis": [{"type": "grammar", "label": "~(으)ㄴ (adjective modifier)", "exp": "Describing words take ~(으)ㄴ before a noun. 신기하다 → 신기한 뱀 = an amazing snake.", "example_in_sentence": "신기한"}, {"type": "grammar", "label": "~이에요", "exp": "Copula (linking verb) polite ending. Identifies or describes the subject. Form: noun + 이에요.", "example_in_sentence": "이에요"}]}, {"text": "이 뱀은 하늘을 날 수 있어요.", "translation": "This snake can fly through the sky.", "vocab": [{"ko": "하늘", "en": "sky"}, {"ko": "날다", "en": "to fly"}], "analysis": [{"type": "grammar", "label": "~을", "exp": "Object particle marking direct object. Used after nouns ending in consonants. Form: 하늘 (ends in consonant ㄹ) + 을.", "example_in_sentence": "하늘을"}, {"type": "grammar", "label": "~(으)ㄹ 수 있다 (can)", "exp": "Says someone is able to do something. 날다 → 날 수 있어요 = can fly.", "example_in_sentence": "날 수 있어요"}]}, {"text": "나무에서 나무로 이동해요.", "translation": "It moves from tree to tree.", "vocab": [{"ko": "나무", "en": "tree"}, {"ko": "이동하다", "en": "to move; to relocate"}], "analysis": [{"type": "grammar", "label": "~에서", "exp": "Particle marking location of origin or action. ''From'' or ''at.'' Form: noun + 에서.", "example_in_sentence": "나무에서"}, {"type": "grammar", "label": "~로", "exp": "Particle marking destination or direction. ''To'' or ''toward.'' Form: noun + 로.", "example_in_sentence": "나무로"}, {"type": "grammar", "label": "~해요", "exp": "Present tense polite ending for action verbs. Conjugation: 이동하다 → 이동해요.", "example_in_sentence": "이동해요"}]}, {"text": "마치 새처럼 움직여요.", "translation": "It moves just like a bird.", "vocab": [{"ko": "마치", "en": "just; as if"}, {"ko": "새", "en": "bird"}, {"ko": "움직이다", "en": "to move"}], "analysis": [{"type": "expression", "label": "~처럼", "exp": "Particle expressing similarity or manner. ''Like'' or ''as.'' Form: noun + 처럼.", "example_in_sentence": "새처럼"}, {"type": "grammar", "label": "~아/어요 (polite ending)", "exp": "The everyday polite ending. 움직이다 → 움직여요 (이 + 어요 becomes 여요).", "example_in_sentence": "움직여요"}]}, {"text": "나는 뱀은 아주 멀리 갈 수 있어요.", "translation": "The flying snake can go very far.", "vocab": [{"ko": "멀다", "en": "to be far"}, {"ko": "가다", "en": "to go"}], "analysis": [{"type": "grammar", "label": "~는 (noun modifier)", "exp": "Describes the noun that follows. ㄹ-stem verbs drop ㄹ before ~는: 날다 → 나는 뱀 (a flying snake). (날으는 is a common misspelling.)", "example_in_sentence": "나는"}, {"type": "grammar", "label": "멀리 (far)", "exp": "An adverb made from 멀다 (to be far). 멀리 가다 = to go far.", "example_in_sentence": "멀리"}, {"type": "grammar", "label": "~ㄹ 수 있다", "exp": "Auxiliary expressing possibility/ability. Form: 가다 → 갈 수 있어요.", "example_in_sentence": "갈 수 있어요"}]}, {"text": "100미터까지 날아갈 수 있어요.", "translation": "It can fly up to 100 meters.", "vocab": [{"ko": "미터", "en": "meter (unit)"}, {"ko": "날아가다", "en": "to fly away; to fly off"}], "analysis": [{"type": "grammar", "label": "~까지", "exp": "Particle marking extent or limit. ''Up to'' or ''until.'' Form: noun + 까지.", "example_in_sentence": "100미터까지"}, {"type": "grammar", "label": "~ㄹ 수 있다", "exp": "Auxiliary expressing possibility/ability. Form: 날아가다 → 날아갈 수 있어요.", "example_in_sentence": "날아갈 수 있어요"}]}, {"text": "축구장만큼 긴 거리예요.", "translation": "It is a distance as long as a soccer field.", "vocab": [{"ko": "축구장", "en": "soccer field"}, {"ko": "길다", "en": "to be long"}, {"ko": "거리", "en": "distance"}], "analysis": [{"type": "expression", "label": "~만큼", "exp": "Particle expressing comparison or degree. ''As much as'' or ''about.'' Form: noun + 만큼.", "example_in_sentence": "축구장만큼"}, {"type": "grammar", "label": "~(으)ㄴ (adjective modifier)", "exp": "Describing words take ~(으)ㄴ before a noun. 길다 → 긴 거리 = a long distance (ㄹ drops before ㄴ).", "example_in_sentence": "긴 거리"}, {"type": "grammar", "label": "~예요", "exp": "Copula polite ending (contracted form of ~이에요). Form: noun + 예요.", "example_in_sentence": "예요"}]}, {"text": "이 뱀은 몸을 평평하게 만들어요.", "translation": "This snake flattens its body.", "vocab": [{"ko": "몸", "en": "body"}, {"ko": "평평하다", "en": "to be flat"}, {"ko": "만들다", "en": "to make; to create"}], "analysis": [{"type": "grammar", "label": "~을", "exp": "Object particle marking direct object after nouns ending in consonants. Form: 몸 + 을.", "example_in_sentence": "몸을"}, {"type": "grammar", "label": "~게 (adverb form)", "exp": "Turns a describing word into an adverb. 평평하다 → 평평하게 만들다 = to make (it) flat.", "example_in_sentence": "평평하게"}, {"type": "grammar", "label": "~어요", "exp": "Present tense polite ending. Conjugation: 만들다 → 만들어요.", "example_in_sentence": "만들어요"}]}, {"text": "그러면 공중에서 미끄러져 가요.", "translation": "Then it slides through the air.", "vocab": [{"ko": "공중", "en": "air; sky"}, {"ko": "미끄러지다", "en": "to slide; to slip"}], "analysis": [{"type": "grammar", "label": "그러면 (then, if so)", "exp": "A linking word at the start of a sentence meaning ''then'' or ''if so''.", "example_in_sentence": "그러면"}, {"type": "grammar", "label": "~에서", "exp": "Particle marking location of action. ''In'' or ''at.'' Form: noun + 에서.", "example_in_sentence": "공중에서"}, {"type": "grammar", "label": "~어 가다", "exp": "Auxiliary construction expressing action in progress/continuation. Form: verb stem + 어/아 + 가다. Here: 미끄러지다 → 미끄러져 가요.", "example_in_sentence": "미끄러져 가요"}]}, {"text": "정말 똑똑한 동물이에요.", "translation": "It is truly a smart animal.", "vocab": [{"ko": "정말", "en": "really; truly"}, {"ko": "똑똑하다", "en": "to be smart; to be intelligent"}, {"ko": "동물", "en": "animal"}], "analysis": [{"type": "grammar", "label": "~(으)ㄴ (adjective modifier)", "exp": "Describing words take ~(으)ㄴ before a noun. 똑똑하다 → 똑똑한 동물 = a smart animal.", "example_in_sentence": "똑똑한"}, {"type": "grammar", "label": "~이에요", "exp": "Copula polite ending. Identifies or describes the subject. Form: noun + 이에요.", "example_in_sentence": "이에요"}]}], "version": "s6"}', updated_at = now() where article_id = 'moknuz8x5kiz' and md5(translation) = '309304cf3b11799cffd66faaa313166d';
update public.article_cache set translation = '{"texts": ["President John F. Kennedy suffered from severe chronic back pain for several years. President John F. Kennedy suffered from severe chronic back pain for several years. This pain had a significant impact on his daily life.", "Kennedy underwent a total of four surgeries to resolve his back problems. The surgeries included disk removal and spinal fusion procedures. He also received two minor surgeries.", "However, despite all these numerous surgeries, Kennedy''s pain continued. The surgeries were not able to completely resolve his back problems.", "President Kennedy carried out his presidential duties despite bearing such physical pain. He tried to overcome his health problems."], "sentences": [{"text": "존 피츠제럴드 케네디 케네디 대통령은 수년 동안 심각한 만성 허리 통증으로 고생했습니다.", "translation": "President John F. Kennedy suffered from severe chronic back pain for several years.", "vocab": [{"ko": "대통령", "en": "president", "note": ""}, {"ko": "고생하다", "en": "to suffer, to have a hard time", "note": ""}, {"ko": "심각하다", "en": "to be serious, severe", "note": ""}, {"ko": "만성", "en": "chronic", "note": "medical term"}, {"ko": "통증", "en": "pain", "note": ""}], "analysis": [{"type": "grammar", "label": "~았/었/였습니다 (past formal)", "exp": "past formal-polite (vowel-contracted form). 고생하다 → 고생했습니다", "example_in_sentence": "고생했습니다"}, {"type": "grammar", "label": "~(으)로 고생하다", "exp": "''to suffer from N''; (으)로 marks the cause: 허리 통증으로 고생했습니다 = suffered from back pain.", "example_in_sentence": "통증으로 고생했습니다"}]}, {"text": "이 통증은 그의 일상생활에 큰 영향을 미쳤어요.", "translation": "This pain had a significant impact on his daily life.", "vocab": [{"ko": "일상생활", "en": "daily life", "note": ""}, {"ko": "영향", "en": "influence, impact", "note": ""}, {"ko": "미치다", "en": "to have an effect, to influence", "note": ""}], "analysis": [{"type": "grammar", "label": "~았/었/였어요 (past polite)", "exp": "past polite (vowel-contracted form). 미치다 → 미쳤어요", "example_in_sentence": "미쳤어요"}]}, {"text": "케네디는 허리 문제를 해결하기 위해 총 네 번의 수술을 받았습니다.", "translation": "Kennedy underwent a total of four surgeries to resolve his back problems.", "vocab": [{"ko": "해결하다", "en": "to solve, to resolve", "note": ""}, {"ko": "수술", "en": "surgery, operation", "note": ""}, {"ko": "받다", "en": "to receive", "note": ""}], "analysis": [{"type": "grammar", "label": "~았/었/였습니다 (past formal)", "exp": "past formal-polite ending. 받다 → 받았습니다", "example_in_sentence": "받았습니다"}, {"type": "grammar", "label": "~기 위해(서) (in order to)", "exp": "purpose. \"in order to / for the sake of\". 해결하다 → 해결하기 위해", "example_in_sentence": "해결하기 위해"}]}, {"text": "수술에는 디스크 제거술과 척추 유합술이 포함되었어요.", "translation": "The surgeries included disk removal and spinal fusion procedures.", "vocab": [{"ko": "제거술", "en": "removal surgery", "note": "medical term"}, {"ko": "척추", "en": "spine, vertebrae", "note": ""}, {"ko": "유합술", "en": "fusion surgery", "note": "medical term"}, {"ko": "포함되다", "en": "to be included", "note": ""}], "analysis": [{"type": "grammar", "label": "~았/었/였어요 (past polite)", "exp": "past polite ending. 포함되다 → 포함되었어요", "example_in_sentence": "포함되었어요"}, {"type": "grammar", "label": "~과/와 (with/and)", "exp": "with / and (formal). 제거술과 척추 유합술 (disk removal and spinal fusion)", "example_in_sentence": "제거술과"}]}, {"text": "또한 두 번의 작은 수술도 받았습니다.", "translation": "He also received two minor surgeries.", "vocab": [{"ko": "또한", "en": "also, in addition", "note": ""}], "analysis": [{"type": "grammar", "label": "~았/었/였습니다 (past formal)", "exp": "past formal-polite ending. 받다 → 받았습니다", "example_in_sentence": "받았습니다"}, {"type": "grammar", "label": "~도 (also)", "exp": "inclusive. \"also / too\". 수술도 (surgery too/also)", "example_in_sentence": "수술도"}]}, {"text": "하지만 이런 많은 수술에도 불구하고 케네디의 통증은 계속되었습니다.", "translation": "However, despite all these numerous surgeries, Kennedy''s pain continued.", "vocab": [{"ko": "계속되다", "en": "to continue", "note": ""}], "analysis": [{"type": "grammar", "label": "~았/었/였습니다 (past formal)", "exp": "past formal-polite ending. 계속되다 → 계속되었습니다", "example_in_sentence": "계속되었습니다"}, {"type": "grammar", "label": "~지만 (but)", "exp": "contrast. \"but / however\". 하다 → 하지만", "example_in_sentence": "하지만"}, {"type": "expression", "label": "~에도 불구하고 (despite)", "exp": "concession. \"despite / in spite of\". 수술에도 불구하고 (despite the surgeries)", "example_in_sentence": "수술에도 불구하고"}]}, {"text": "수술들이 그의 허리 문제를 완전히 해결하지는 못했어요.", "translation": "The surgeries were not able to completely resolve his back problems.", "vocab": [{"ko": "완전히", "en": "completely", "note": ""}], "analysis": [{"type": "grammar", "label": "~지는 못하다", "exp": "''could not (fully) V''; 는 adds contrast: 해결하다 → 해결하지는 못했어요 (did not completely solve it).", "example_in_sentence": "해결하지는 못했어요"}, {"type": "grammar", "label": "~았/었/였어요 (past polite)", "exp": "past polite (vowel-contracted form). 못하다 → 못했어요", "example_in_sentence": "못했어요"}, {"type": "grammar", "label": "~히 (adverb suffix, Sino-Korean)", "exp": "adverbializer for Sino-Korean and a few native bases. 완전하다 → 완전히 (completely)", "example_in_sentence": "완전히"}]}, {"text": "케네디 대통령은 이러한 신체적 고통을 안고도 대통령직을 수행했습니다.", "translation": "President Kennedy carried out his presidential duties despite bearing such physical pain.", "vocab": [{"ko": "신체적", "en": "physical", "note": ""}, {"ko": "고통", "en": "pain, suffering", "note": ""}, {"ko": "안다", "en": "to hold, to carry", "note": ""}, {"ko": "수행하다", "en": "to perform, to carry out", "note": ""}], "analysis": [{"type": "grammar", "label": "~았/었/였습니다 (past formal)", "exp": "past formal-polite (vowel-contracted form). 수행하다 → 수행했습니다", "example_in_sentence": "수행했습니다"}, {"type": "grammar", "label": "~고도 / ~면서도 (despite)", "exp": "despite doing / while still being. 안다 → 안고도 (despite carrying)", "example_in_sentence": "안고도"}]}, {"text": "그는 자신의 건강 문제를 극복하려고 노력했어요.", "translation": "He tried to overcome his health problems.", "vocab": [{"ko": "극복하다", "en": "to overcome", "note": ""}, {"ko": "노력하다", "en": "to make an effort, to try hard", "note": ""}], "analysis": [{"type": "grammar", "label": "~았/었/였어요 (past polite)", "exp": "past polite (vowel-contracted form). 노력하다 → 노력했어요", "example_in_sentence": "노력했어요"}, {"type": "grammar", "label": "~(으)려고 (intention)", "exp": "in order to / intending to. 극복하다 → 극복하려고", "example_in_sentence": "극복하려고"}]}], "version": "s6"}', updated_at = now() where article_id = 'mp1ui888zwor' and md5(translation) = 'd4dfdafd289ffb8d8f18724e4973ee3f';
